from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    threshold = 0.65

    rows = []
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if color != bg and count / w >= threshold:
            rows.append(r)

    cols = []
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color != bg and count / h >= threshold:
            cols.append(c)

    # A repeated edge value may extend the first vertical grid line to column 0.
    if len(cols) > 1 and cols[0] == 0:
        cols = cols[1:]

    return [[grid[r][c] for c in cols[:-1]] for r in rows[:-1]]
